-- Synthetic-only test data. Every write, including Storage metadata, rolls back.
begin;
set local lock_timeout='5s';set local statement_timeout='40s';
create temporary table platform_probe(a uuid,b uuid,c uuid,admin uuid,asset uuid,post uuid,private_post uuid,connection_post uuid,call uuid,location uuid,client uuid) on commit drop;
insert into platform_probe(a,b,c,admin,client) values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid());
grant all on platform_probe to authenticated;
insert into public.users(id,email) select id,'platform-probe-'||id||'@example.invalid' from(select a id from platform_probe union all select b from platform_probe union all select c from platform_probe union all select admin from platform_probe)x;
insert into public.profiles(user_id,display_name,onboarding_completed,discoverable) select id,'Platform probe',true,true from(select a id from platform_probe union all select b from platform_probe union all select c from platform_probe union all select admin from platform_probe)x;
insert into public.connections(user_a,user_b) select least(a,b),greatest(a,b) from platform_probe;
insert into public.user_roles(user_id,role) select admin,'admin' from platform_probe;
insert into public.user_sessions(user_id,auth_session_id) select b,'platform-b' from platform_probe;
select set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated','session_id','platform-a')::text,true) from platform_probe;
set local role authenticated;
do $$ declare r jsonb; x uuid; begin
 r:=public.sidle_platform('preferences.set','{"analyticsConsent":true,"labels":{}}');if r->>'analyticsConsent'<>'true' then raise exception 'Preference persistence';end if;
 r:=public.sidle_platform('profile.details.set',jsonb_build_object('handle','probe_'||(select left(a::text,8) from pg_temp.platform_probe),'campus','Test campus','course','Test course','audience','connections'));
 if r->>'campus'<>'Test campus' then raise exception 'Profile persistence';end if;
 r:=public.sidle_platform('media.reserve',jsonb_build_object('clientId',(select client from pg_temp.platform_probe),'kind','image','mime','image/jpeg','sizeBytes',14,'durationSeconds',0,'rights','original'));
 update pg_temp.platform_probe set asset=(r->>'id')::uuid;
 if r is distinct from public.sidle_platform('media.reserve',jsonb_build_object('clientId',(select client from pg_temp.platform_probe),'kind','image','mime','image/jpeg','sizeBytes',14,'durationSeconds',0,'rights','original')) then raise exception 'Media reservation retry';end if;
 begin perform public.sidle_platform('media.finalize',jsonb_build_object('id',(select asset from pg_temp.platform_probe)));raise exception 'Missing blob accepted';exception when invalid_parameter_value then null;end;
 begin perform public.sidle_platform('media.reserve',jsonb_build_object('clientId',gen_random_uuid(),'kind','video','mime','video/mp4','sizeBytes',20971521,'durationSeconds',1,'rights','original'));raise exception 'Oversized upload';exception when invalid_parameter_value then null;end;
 begin perform public.sidle_platform('media.reserve',jsonb_build_object('clientId',gen_random_uuid(),'kind','audio','mime','audio/mpeg','sizeBytes',14,'durationSeconds',10,'rights','cc_by'));raise exception 'Missing attribution accepted';exception when invalid_parameter_value then null;end;
 begin perform public.sidle_platform('location.start',jsonb_build_object('recipients',jsonb_build_array((select c from pg_temp.platform_probe)),'latitude',-20.15,'longitude',28.58,'minutes',15));raise exception 'Outsider location share';exception when insufficient_privilege then null;end;
end; $$;
reset role;
insert into storage.objects(bucket_id,name,metadata,owner_id) select 'sidle-social-media',s.path,'{"size":14,"mimetype":"image/jpeg"}',p.a::text from app_private.social_assets s join platform_probe p on p.asset=s.id;
set local role authenticated;
do $$ declare r jsonb; begin
 r:=public.sidle_platform('media.finalize',jsonb_build_object('id',(select asset from pg_temp.platform_probe)));if r->>'status'<>'ready' then raise exception 'Media finalize';end if;
 r:=public.sidle_platform('posts.create',jsonb_build_object('clientId',(select client from pg_temp.platform_probe),'kind','post','body','Public test post','assetId',(select asset from pg_temp.platform_probe),'audience','public'));update pg_temp.platform_probe set post=(r->>'id')::uuid;
 if r->>'body'<>'Public test post' then raise exception 'Post render';end if;
 if r is distinct from public.sidle_platform('posts.create',jsonb_build_object('clientId',(select client from pg_temp.platform_probe),'kind','post','body','Public test post','assetId',(select asset from pg_temp.platform_probe),'audience','public')) then raise exception 'Post retry';end if;
 r:=public.sidle_platform('posts.create',jsonb_build_object('clientId',gen_random_uuid(),'kind','post','body','Private test post','audience','private'));update pg_temp.platform_probe set private_post=(r->>'id')::uuid;
 r:=public.sidle_platform('posts.create',jsonb_build_object('clientId',gen_random_uuid(),'kind','post','body','Connections test post','audience','connections'));update pg_temp.platform_probe set connection_post=(r->>'id')::uuid;
 if jsonb_array_length(public.sidle_platform('posts.list','{}')->'items')<3 then raise exception 'Own feed';end if;
 perform public.sidle_platform('telemetry','{"event":"app_open"}');
 if public.sidle_platform('account.export','{}')->'preferences'->>'analyticsConsent'<>'true' then raise exception 'Account export';end if;
end; $$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated','session_id','platform-c')::text,true) from platform_probe;
set local role authenticated;
do $$ declare r jsonb; begin
 r:=public.sidle_platform('profile.details.get',jsonb_build_object('userId',(select a from pg_temp.platform_probe)));if r->'campus'<>'null'::jsonb then raise exception 'Private profile detail leak';end if;
 if public.sidle_platform('posts.get',jsonb_build_object('id',(select private_post from pg_temp.platform_probe))) is not null then raise exception 'Private post leak';end if;
 if public.sidle_platform('posts.get',jsonb_build_object('id',(select connection_post from pg_temp.platform_probe))) is not null then raise exception 'Connection post leak';end if;
 perform public.sidle_platform('posts.react',jsonb_build_object('id',(select post from pg_temp.platform_probe),'reaction','like'));
 perform public.sidle_platform('posts.bookmark',jsonb_build_object('id',(select post from pg_temp.platform_probe),'saved',true));
 if jsonb_array_length(public.sidle_platform('posts.list','{"scope":"saved"}')->'items')<>1 then raise exception 'Private bookmarks';end if;
 perform public.sidle_platform('posts.comment',jsonb_build_object('id',(select post from pg_temp.platform_probe),'body','A synthetic comment','clientId',gen_random_uuid()));
 if jsonb_array_length(public.sidle_platform('posts.comments',jsonb_build_object('id',(select post from pg_temp.platform_probe))))<>1 then raise exception 'Comments';end if;
 perform public.sidle_platform('people.follow',jsonb_build_object('userId',(select a from pg_temp.platform_probe),'following',true));
 begin perform public.sidle_platform('admin.reports','{}');raise exception 'Admin bypass';exception when insufficient_privilege then null;end;
 begin perform 1 from app_private.social_posts;raise exception 'Direct table bypass';exception when insufficient_privilege then null;end;
 perform public.sidle_platform('reports.create',jsonb_build_object('postId',(select post from pg_temp.platform_probe),'reason','spam','details','Synthetic report'));
end; $$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated','session_id','platform-b')::text,true) from platform_probe;
set local role authenticated;
do $$ declare r jsonb; begin
 if public.sidle_platform('profile.details.get',jsonb_build_object('userId',(select a from pg_temp.platform_probe)))->>'campus'<>'Test campus' then raise exception 'Connection field visibility';end if;
 if public.sidle_platform('posts.get',jsonb_build_object('id',(select connection_post from pg_temp.platform_probe))) is null then raise exception 'Connection post hidden';end if;
 r:=public.sidle_platform('location.start',jsonb_build_object('recipients',jsonb_build_array((select a from pg_temp.platform_probe)),'latitude',-20.15,'longitude',28.58,'accuracy',10,'minutes',15));update pg_temp.platform_probe set location=(r->>'id')::uuid;
 r:=public.sidle_platform('calls.start',jsonb_build_object('userId',(select a from pg_temp.platform_probe),'mode','audio'));update pg_temp.platform_probe set call=(r->>'id')::uuid;
 perform public.sidle_platform('calls.signal',jsonb_build_object('id',(select call from pg_temp.platform_probe),'kind','offer','payload','{"type":"offer","sdp":"synthetic"}'::jsonb));
end; $$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated','session_id','platform-c')::text,true) from platform_probe;
set local role authenticated;
do $$ begin
 if public.sidle_platform('location.list','{}')<>'[]'::jsonb then raise exception 'Precise location outsider leak';end if;
 begin perform public.sidle_platform('calls.signals',jsonb_build_object('id',(select call from pg_temp.platform_probe)));raise exception 'Call signal outsider leak';exception when insufficient_privilege then null;end;
end; $$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated','session_id','platform-a')::text,true) from platform_probe;
set local role authenticated;
do $$ begin
 if jsonb_array_length(public.sidle_platform('location.list','{}'))<>1 then raise exception 'Selected recipient missing location';end if;
 if jsonb_array_length(public.sidle_platform('calls.signals',jsonb_build_object('id',(select call from pg_temp.platform_probe))))<>1 then raise exception 'Participant missing signal';end if;
 perform public.sidle_platform('calls.state',jsonb_build_object('id',(select call from pg_temp.platform_probe),'state','accepted'));
 if jsonb_array_length(public.sidle_platform('activity.list','{}'))<1 then raise exception 'Activity inbox';end if;
 perform public.sidle_platform('activity.read','{}');
end; $$;
reset role;
update app_private.location_shares set expires_at=now()-interval '1 second' where id=(select location from platform_probe);
set local role authenticated;
do $$ begin if public.sidle_platform('location.list','{}')<>'[]'::jsonb then raise exception 'Expired location leak';end if;end; $$;
reset role;
insert into public.user_blocks(blocker_id,blocked_id) select a,b from platform_probe;
select set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated','session_id','platform-b')::text,true) from platform_probe;
set local role authenticated;
do $$ begin
 if public.sidle_platform('posts.get',jsonb_build_object('id',(select post from pg_temp.platform_probe))) is not null then raise exception 'Blocked public post leak';end if;
 begin perform public.sidle_platform('calls.signals',jsonb_build_object('id',(select call from pg_temp.platform_probe)));raise exception 'Blocked call signal leak';exception when insufficient_privilege then null;end;
end; $$;
reset role;
update public.user_sessions set revoked_at=now() where user_id=(select b from platform_probe);
set local role authenticated;
do $$ begin begin perform public.sidle_platform('posts.list','{}');raise exception 'Revoked platform session';exception when insufficient_privilege then null;end;end; $$;
reset role;
update app_private.social_assets set status='quarantined' where id=(select asset from platform_probe);
select set_config('request.jwt.claims',jsonb_build_object('sub',admin,'role','authenticated','session_id','platform-admin')::text,true) from platform_probe;
set local role authenticated;
do $$ declare r jsonb; begin
 r:=public.sidle_platform('admin.reports','{}');if jsonb_array_length(r)<1 then raise exception 'Admin reports';end if;
 perform public.sidle_platform('admin.report.resolve',jsonb_build_object('id',r->0->>'id','status','resolved'));
 perform public.sidle_platform('admin.usage','{}');perform public.sidle_platform('admin.analytics','{}');
 perform public.sidle_platform('admin.settings','{"uploadsEnabled":false}');
 begin perform public.sidle_platform('admin.settings','{"adminMfaRequired":true}');raise exception 'MFA requirement enabled without a verified factor';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',(current_setting('request.jwt.claims')::jsonb||'{"aal":"aal2"}'::jsonb)::text,true);
 perform public.sidle_platform('admin.settings','{"adminMfaRequired":true}');
 perform set_config('request.jwt.claims',(current_setting('request.jwt.claims')::jsonb- 'aal')::text,true);
 begin perform public.sidle_platform('admin.usage','{}');raise exception 'Admin MFA bypass';exception when insufficient_privilege then null;end;
 if public.sidle_social_media_read((select a::text||'/'||asset::text||'.jpg' from pg_temp.platform_probe)) then raise exception 'MFA bypass through quarantine Storage reads';end if;
 perform set_config('request.jwt.claims',(current_setting('request.jwt.claims')::jsonb||'{"aal":"aal2"}'::jsonb)::text,true);
 perform public.sidle_platform('admin.settings','{"adminMfaRequired":false}');
end; $$;
reset role;
update public.users set status='deleted' where id=(select a from platform_probe);
do $$ begin
 if exists(select 1 from app_private.social_posts where user_id=(select a from platform_probe) and (state<>'deleted' or body<>'')) then raise exception 'Post anonymization';end if;
 if exists(select 1 from app_private.profile_details where user_id=(select a from platform_probe)) then raise exception 'Profile detail anonymization';end if;
end; $$;
rollback;
select 'PASS: media reservations/finalization, content audiences/retries, comments/reactions/bookmarks/follows, profile ACL, location consent/expiry, call membership, moderation, preferences/export, revocation/block/deletion; fixtures rolled back' as result;
